package com.animalloo.ui.pet;
import android.net.Uri; import android.os.Bundle; import android.text.TextUtils; import android.view.View;
import androidx.activity.result.ActivityResultLauncher; import androidx.activity.result.contract.ActivityResultContracts; import androidx.annotation.Nullable; import androidx.appcompat.app.AppCompatActivity;
import com.animalloo.R; import com.animalloo.data.model.HomeProfile; import com.animalloo.data.model.PetProfileInput; import com.animalloo.data.repository.RepositoryCallback; import com.animalloo.databinding.ActivityPetProfileBinding; import com.animalloo.util.ImageFileHelper; import com.animalloo.util.RepositoryProvider; import com.bumptech.glide.Glide; import com.google.android.material.snackbar.Snackbar; import java.io.File; import java.io.IOException;
public class PetProfileActivity extends AppCompatActivity {
 private ActivityPetProfileBinding binding; private File photoFile;
 private final ActivityResultLauncher<String> picker=registerForActivityResult(new ActivityResultContracts.GetContent(),this::picked);
 @Override public void onCreate(@Nullable Bundle b){super.onCreate(b);binding=ActivityPetProfileBinding.inflate(getLayoutInflater());setContentView(binding.getRoot());binding.toolbarPetProfile.setNavigationOnClickListener(v->finish());binding.btnPetPhoto.setOnClickListener(v->picker.launch("image/*"));binding.btnSavePet.setOnClickListener(v->save());load();}
 private void load(){RepositoryProvider.getInstance().getHomeRepository().getHomeProfile(null,new RepositoryCallback<HomeProfile>(){@Override public void onSuccess(HomeProfile p){runOnUiThread(()->bind(p));}@Override public void onError(String m){}});}
 private void bind(HomeProfile p){if(!p.hasPet())return;binding.etPetName.setText(p.getPetName());binding.etPetBreed.setText(p.getPetBreed());binding.etPetAge.setText(p.getPetAge());binding.etPetSpecies.setText(p.getPetSpecies());binding.etPetGender.setText(p.getPetGender());binding.etPetNeutered.setText(p.getPetNeutered());if(p.getPetWeightKg()!=null)binding.etPetWeight.setText(String.valueOf(p.getPetWeightKg()));binding.etPetBirthDate.setText(p.getPetBirthDate());binding.etPetAdoptionDate.setText(p.getPetAdoptionDate());if(!TextUtils.isEmpty(p.getPetPhotoUrl()))Glide.with(this).load(p.getPetPhotoUrl()).into(binding.ivPetPhoto);}
 private void picked(Uri u){if(u==null)return;try{photoFile=ImageFileHelper.copyUriToCache(this,u);Glide.with(this).load(photoFile).into(binding.ivPetPhoto);binding.ivPetPhoto.setVisibility(View.VISIBLE);}catch(IOException e){Snackbar.make(binding.getRoot(),R.string.lost_report_photo_copy_failed,Snackbar.LENGTH_SHORT).show();}}
 private void save(){String n=v(binding.etPetName);if(n.isEmpty()){binding.tilPetName.setError(getString(R.string.pet_registration_name_required));return;}Double w=null;try{if(!v(binding.etPetWeight).isEmpty())w=Double.valueOf(v(binding.etPetWeight));}catch(NumberFormatException e){binding.tilPetWeight.setError(getString(R.string.pet_weight_invalid));return;}binding.btnSavePet.setEnabled(false);PetProfileInput p=new PetProfileInput(n,e(v(binding.etPetBreed)),e(v(binding.etPetAge)),e(v(binding.etPetSpecies)),e(v(binding.etPetGender)),e(v(binding.etPetNeutered)),w,e(v(binding.etPetBirthDate)),e(v(binding.etPetAdoptionDate)));RepositoryProvider.getInstance().getHomeRepository().upsertPet(p,photoFile,new RepositoryCallback<HomeProfile>(){@Override public void onSuccess(HomeProfile x){runOnUiThread(()->finish());}@Override public void onError(String m){runOnUiThread(()->{binding.btnSavePet.setEnabled(true);Snackbar.make(binding.getRoot(),m,Snackbar.LENGTH_LONG).show();});}});}
 private static String v(android.widget.EditText e){return e.getText()==null?"":e.getText().toString().trim();}private static String e(String v){return v.isEmpty()?null:v;}
}
